    <div class="orion-inv-edit"><div class="ie-kpis"><div class="ie-kpi" style="--accent:var(--ie-blue)"><div class="ie-kpi-label">إجمالي الفاتورة</div><div class="ie-kpi-value">{{ number_format($total,2) }} ر.س</div><div class="ie-kpi-note">بعد الخصم والضريبة</div></div><div class="ie-kpi" style="--accent:var(--ie-green)"><div class="ie-kpi-label">المدفوع</div><div class="ie-kpi-value">{{ number_format($paid,2) }} ر.س</div><div class="ie-kpi-note">{{ $paidPct }}% من الإجمالي</div></div><div class="ie-kpi" style="--accent:{{ $remaining > 0 ? 'var(--ie-red)' : 'var(--ie-green)' }}"><div class="ie-kpi-label">المتبقي</div><div class="ie-kpi-value">{{ number_format($remaining,2) }} ر.س</div><div class="ie-kpi-note">{{ $remaining > 0 ? 'رصيد مفتوح' : 'مسدد بالكامل' }}</div></div><div class="ie-kpi" style="--accent:var(--ie-purple)"><div class="ie-kpi-label">الضريبة</div><div class="ie-kpi-value">{{ number_format((float)$record->tax_amount,2) }} ر.س</div><div class="ie-kpi-note">قيمة VAT المسجلة</div></div></div>
